	void nativeReadFailureDoesNotPublishPropertiesAndReleasesOwners(Generation generation,
			@TempDir Path directory) throws Exception {
		generation.create(directory);
		Path data = directory.resolve("values/data.mdb");
		byte[] authentic = Files.readAllBytes(data);
		Files.write(data, new byte[] { 0, 0, 0, 0 });
		Map<String, String> before = LmdbCompatibilityFixtures.snapshot(directory);
		ObservingStore rejected = new ObservingStore(directory, false, false);
		try {
			SailException failure = assertThrows(SailException.class, rejected::init);
			assertTrue(rootCause(failure) instanceof IOException, "native read failure must remain an IO failure");
		} finally {
			rejected.shutDown();
		}
		assertEquals(before, LmdbCompatibilityFixtures.snapshot(directory));
		assertFalse(rejected.backingEntered);
		assertLockReleased(directory);
		// This test owns the deliberately corrupted closed-store copy. Restoring its authentic bytes and
		// opening normally proves that the failed read probe released its environment, transaction and lock.
		Files.write(data, authentic);
		assertSuccessfulOpenAndReopen(directory);
	}

