	@ParameterizedTest
	@MethodSource("recoveryCases")
	void knownButUntrustedMarkerRetainsExistingRecoveryAndDowngradePolicy(Generation generation, boolean repair,
			@TempDir Path directory) throws Exception {
		generation.create(directory);
		LmdbCompatibilityFixtures.nativePut(directory, "ref_counts", MARKER_KEY, Marker.KNOWN_SHORT_HEADER.bytes());
		LmdbStoreConfig config = config().setLegacyReferenceCountRepairEnabled(repair);
		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile(), config));
		repository.init();
		try (var connection = repository.getConnection()) {
			assertEquals(1L, connection.size(), "reconciliation must preserve the real fixture statement");
		} finally {
			repository.shutDown();
		}
		byte[] marker = LmdbCompatibilityFixtures.nativeGet(directory, "ref_counts", MARKER_KEY);
		if (generation == Generation.LEGACY && !repair) {
			assertEquals(null, marker, "legacy no-repair startup strips a structured marker for older readers");
		} else {
			assertNotNull(marker);
			assertEquals(18, marker.length);
			ByteBuffer encoded = ByteBuffer.wrap(marker);
			assertEquals(0x52434654, encoded.getInt());
			assertEquals(1, encoded.get());
			assertEquals(1, encoded.get(), "the completed close owns a clean marker");
			assertTrue(encoded.getLong() >= 0L);
			CRC32 crc = new CRC32();
			crc.update(marker, 0, marker.length - Integer.BYTES);
			assertEquals((int) crc.getValue(), encoded.getInt());
		}
		StoreProperties properties = new StoreProperties(directory.toFile());
		assertTrue(properties.load());
		assertEquals(generation == Generation.LEGACY ? "2" : "6", properties.getVersion());
	}

